import { getAllProducts } from '@/lib/db';
import { cacheTag, revalidateTag } from 'next/cache';

interface Product {
  id: number;
  name: string;
  price: number;
}

async function ProductList() {
  'use cache';
  cacheTag('products');

  const products: Product[] = await getAllProducts();

  return (
    <div className="p-4 border rounded-lg bg-gray-50">
      <h2 className="text-xl font-semibold mb-3">Products (Cached)</h2>
      <ul className="space-y-2">
        {products.map((product) => (
          <li key={product.id} className="flex justify-between p-2 bg-white rounded shadow-sm">
            <span>{product.name}</span>
            <span className="font-mono text-gray-600">${product.price}</span>
          </li>
        ))}
      </ul>
      <p className="text-xs text-gray-400 mt-2">
        Fetched at: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

function InvalidateCache() {
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <form action={invalidateProducts} className="mt-6">
      <button 
        type="submit"
        className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
      >
        Invalidate "products" Cache
      </button>
    </form>
  );
}

export default function Page() {
  return (
    <main className="min-h-screen p-8 max-w-2xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Product Cache Demo</h1>

      <div className="space-y-8">
        <ProductList />
        <InvalidateCache />
      </div>
    </main>
  );
}

